
CREATE TABLE public.rms_reset_service_routes (
 public_service_slug text PRIMARY KEY,
 service_key text NOT NULL REFERENCES public.rms_studio_service_catalog(service_key),
 payment_lane text NOT NULL CHECK (payment_lane IN ('reset_media_studios','reset_live_events')),
 route_enabled boolean NOT NULL DEFAULT false CHECK (NOT route_enabled),
 quote_required boolean NOT NULL DEFAULT true CHECK (quote_required),
 auto_fulfillment_enabled boolean NOT NULL DEFAULT false CHECK (NOT auto_fulfillment_enabled),
 updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.rms_reset_service_routes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.rms_reset_service_routes FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.rms_reset_service_routes TO service_role;

